const SERIES = [
    { key: "drafting", label: "Drafting", color: "art:bg-blue-500", stroke: "art:stroke-blue-500" },
    { key: "analysis", label: "Analysis", color: "art:bg-orange-500", stroke: "art:stroke-orange-500" },
    { key: "translation", label: "Translation", color: "art:bg-teal-500", stroke: "art:stroke-teal-500" },
    { key: "sync", label: "Data sync", color: "art:bg-lime-500", stroke: "art:stroke-lime-500" },
] as const;
type SeriesKey = (typeof SERIES)[number]["key"];
const DAYS: readonly (readonly [
    number,
    number,
    number,
    number
])[] = [
    [3753, 4750, 2674, 2381],
    [3761, 4050, 2454, 1684],
    [4020, 4974, 2443, 1761],
    [1611, 2100, 1301, 957],
    [1896, 2546, 1322, 919],
    [4130, 4597, 2808, 2280],
    [3352, 4278, 2124, 2073],
    [3975, 4410, 2392, 1807],
    [3653, 4493, 2363, 2199],
    [4583, 5740, 2726, 2049],
    [2313, 2376, 1196, 1170],
    [2417, 3180, 1735, 1317],
    [4447, 6033, 3381, 2701],
    [4205, 5804, 2855, 2741],
    [5032, 5148, 2912, 2397],
    [4401, 5253, 3225, 2514],
    [5285, 5138, 3144, 2628],
    [2155, 2507, 1638, 1065],
    [1833, 2624, 1485, 957],
    [5053, 6681, 3521, 2855],
    [5602, 6136, 3126, 2783],
    [5178, 6899, 3697, 2589],
    [7227, 7462, 4531, 3216],
];
const CYCLE_DAYS = 30;
const TODAY = DAYS.length - 1;
const DOMAIN = Math.max(...DAYS.map((d) => d[0] + d[1] + d[2] + d[3])) * 1.08;
const BUDGET = Math.round(500000 / CYCLE_DAYS);
type Range = "14d" | "cycle";
const RANGES = [
    { value: "14d", label: <>{"14"}{" days"}</> },
    { value: "cycle", label: "Full cycle" },
] as const;
const WORKFLOWS = [
    { name: "Ticket triage", series: 1, points: "0.0,21.5 4.9,22.3 9.8,20.3 14.8,17.2 19.7,20.7 24.6,17.6 29.5,14.5 34.5,8.7 39.4,9.1 44.3,14.5 49.2,4.8 54.2,5.6 59.1,7.9 64.0,1.8", value: "46.3k", up: true, pct: "18" },
    { name: "Market scan", series: 1, points: "0.0,9.4 4.9,22.3 9.8,3.5 14.8,6.0 19.7,13.7 24.6,1.8 29.5,12.0 34.5,6.9 39.4,12.9 44.3,1.8 49.2,6.0 54.2,2.6 59.1,6.9 64.0,12.0", value: "38.1k", up: true, pct: "6" },
    { name: "Help localizer", series: 2, points: "0.0,8.8 4.9,1.8 9.8,6.0 14.8,5.3 19.7,10.9 24.6,16.6 29.5,14.5 34.5,12.4 39.4,22.3 44.3,20.1 49.2,16.6 54.2,7.4 59.1,13.1 64.0,22.3", value: "33.6k", up: false, pct: "9" },
    { name: "CRM enrichment", series: 3, points: "0.0,22.3 4.9,18.9 9.8,14.3 14.8,4.4 19.7,8.4 24.6,15.6 29.5,13.0 34.5,16.3 39.4,9.0 44.3,1.8 49.2,2.4 54.2,9.7 59.1,4.4 64.0,7.0", value: "29.5k", up: true, pct: "3" },
    { name: "Proposal drafts", series: 0, points: "0.0,22.3 4.9,15.7 9.8,14.3 14.8,18.1 19.7,12.9 24.6,12.9 29.5,7.3 34.5,11.5 39.4,12.5 44.3,5.0 49.2,1.8 54.2,6.4 59.1,1.8 64.0,4.5", value: "27.9k", up: true, pct: "24" },
] as const;
const k = (v: number) => (v < 1000 ? `${v}` : `${(v / 1000).toFixed(1)}k`);
const pct = (v: number) => `${v}%`;
const num = (v: number) => v.toLocaleString("en-US");
const BAR = "art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:flex art:h-full art:min-w-0 art:flex-1 art:items-end art:disabled:opacity-100 art:rounded-full";
const LEGEND = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:h-8 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:transition-opacity";
const DIM = { duration: 0.18, ease: "easeOut" } as const;
const TIP_EXIT = { duration: 0.14, ease: [0.4, 0, 1, 1] } as const;
const REVEAL_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 14 };
const REVEAL_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const reveal = (delay: number) => ({ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay });
export default function CreditUsageTrend() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion();
    const [range, setRange] = useState<Range>("cycle");
    const [hidden, setHidden] = useState<ReadonlySet<SeriesKey>>(new Set());
    const [active, setActive] = useState<number | null>(null);
    const [highlight, setHighlight] = useState<number | null>(null);
    const bars = useRef<(HTMLButtonElement | null)[]>([]);
    const visible = SERIES.map((s) => !hidden.has(s.key));
    const totalOf = (day: readonly number[]) => day.reduce((sum, v, i) => sum + (visible[i] ? v : 0), 0);
    const used = DAYS.reduce((sum, d) => sum + totalOf(d), 0);
    const average = Math.round(used / DAYS.length);
    const projected = average * CYCLE_DAYS;
    const first = range === "cycle" ? 0 : DAYS.length - 14;
    const shown = DAYS.slice(first);
    const projectedCount = range === "cycle" ? CYCLE_DAYS - DAYS.length : 0;
    const count = shown.length + projectedCount;
    const last = shown.length - 1;
    const grow = (i: number) => (reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_LAYOUT, delay: 0.3 + i * 0.018 });
    const instant = (t: object) => (reduce ? { duration: 0 } : t);
    const toggle = (key: SeriesKey) => setHidden((prev) => {
