            return;
        e.preventDefault();
        bars.current[to]?.focus();
    };
    const tip = active === null || active > last
        ? null
        : (() => {
            const day = shown[active];
            const total = totalOf(day);
            const left = ((active + 0.5) / count) * 100;
            return { day, total, left, top: Math.min(48, (1 - total / DOMAIN) * 100 - 4), flip: left > 54.9, date: first + active + 1 };
        })();
    const roving = active ?? last;
    return (<>
