        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <motion.div className="art:flex art:flex-col art:gap-5 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-end art:@min-[640px]/artemis:justify-between" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0))}>
            <div>
              <h2 id={`${artemisInstanceId}-credit-trend-title`} className="art:font-medium art:text-4xl art:tracking-tight">
                {"Daily credit spend"}
              </h2>
              <p className="art:mt-2 art:text-muted-foreground">{"Track the pace of this cycle and spot the days that ran hot."}</p>
            </div>
            <div>
              <ArtemisSegmentedTabs items={RANGES} value={range} onValueChange={(v) => {
            setActive(null);
            setRange(v as Range);
        }} ariaLabel="Chart range" layout="position"/>
            </div>
          </motion.div>
          <motion.dl className="art:mt-8 art:grid art:gap-4 art:@min-[640px]/artemis:grid-cols-3" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.08))}>
            <Stat label="Used so far" value={num(used)}/>
            <Stat label="Daily average" value={num(average)}/>
            <Stat label="Projected by Nov 1" value={num(projected)} badge={<span className="art:rounded-full art:border art:px-2 art:py-0.5 art:font-medium art:text-xs art:border-emerald-500/25 art:bg-emerald-500/10 art:text-emerald-700 art:dark:text-emerald-300" style={{ opacity: 1, transform: "none" }}>
                  {"On pace"}
                </span>}/>
          </motion.dl>
          <div className="art:mt-4 art:grid art:gap-4 art:@min-[1024px]/artemis:grid-cols-[minmax(0,1fr)_20rem]">
            <motion.div className="art:min-w-0 art:rounded-3xl art:border art:border-border art:p-5 art:@min-[640px]/artemis:p-6" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.16))}>
              <div className="art:flex art:items-baseline art:justify-between art:gap-3">
                <h3 className="art:font-medium art:text-xl">{"Spend per day"}</h3>
                <p className="art:hidden art:text-muted-foreground art:text-xs art:@min-[640px]/artemis:block">{"Hover or use arrow keys to inspect a day"}</p>
              </div>
              <figure aria-label="Spend per day" className="art:m-0 art:w-full art:mt-8">
                <div className="art:relative art:h-64">
                  <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:z-10 art:border-foreground/30 art:border-t art:border-dashed" style={{ bottom: `${(BUDGET / DOMAIN) * 100}%` }}>
                    <span className="art:absolute art:-top-6 art:right-0 art:rounded-full art:border art:border-border art:bg-background art:px-2 art:py-0.5 art:text-muted-foreground art:text-xs">{`Daily budget ${k(BUDGET)}`}</span>
                  </div>
                  <AnimatePresence>
                    {tip && (<motion.div key="tip" aria-hidden="true" className="art:pointer-events-none art:absolute art:z-20" initial={{ opacity: 0, left: pct(tip.left), top: pct(tip.top) }} animate={{ opacity: 1, left: pct(tip.left), top: pct(tip.top) }} exit={{ opacity: 0, transition: instant(TIP_EXIT) }} transition={instant(ARTEMIS_SPRING_SWAP)}>
                        <motion.div className="art:w-48 art:rounded-2xl art:border art:border-border art:bg-background art:p-3" style={{ marginLeft: tip.flip ? -14 : 14, originX: tip.flip ? 1 : 0 }} initial={{ scale: 0.96, x: tip.flip ? "-100%" : 0 }} animate={{ scale: 1, x: tip.flip ? "-100%" : 0 }} transition={instant(ARTEMIS_SPRING_SWAP)}>
                          <div className="art:flex art:items-baseline art:justify-between art:gap-2">
                            <p className="art:font-medium art:text-sm">{`Oct ${tip.date}`}</p>
                            <p className="art:font-mono art:text-xs art:tabular-nums">{k(tip.total)}</p>
                          </div>
                          <ul className="art:mt-2 art:space-y-1">
                            {SERIES.map((s, i) => visible[i] ? (<li key={s.key} className="art:flex art:items-center art:justify-between art:gap-2 art:text-xs">
                                  <span className="art:flex art:items-center art:gap-1.5 art:text-muted-foreground">
                                    <span className={`art:size-1.5 art:rounded-full ${s.color}`}/>
                                    {s.label}
                                  </span>
                                  <span className="art:font-mono art:tabular-nums">{k(tip.day[i])}</span>
                                </li>) : null)}
                          </ul>
                        </motion.div>
                      </motion.div>)}
                  </AnimatePresence>
                  <div className="art:flex art:h-full art:items-end art:gap-1" onPointerLeave={() => setActive(null)}>
                    {shown.map((day, i) => {
            const total = totalOf(day);
            const on = active === i;
            const date = first + i + 1;
            return (<button key={`${range}-${date}`} ref={(el) => {
                    bars.current[i] = el;
                }} type="button" className={BAR} tabIndex={roving === i ? 0 : -1} aria-label={`Oct ${date}: ${k(total)}`} aria-pressed={on} onPointerEnter={() => setActive(i)} onFocus={() => setActive(i)} onBlur={() => setActive((a) => (a === i ? null : a))} onKeyDown={(e) => onBarKey(e, i)}>
                          <span aria-hidden="true" className={`art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 ${on ? "art:opacity-100" : "art:opacity-0"}`}/>
                          <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: total / DOMAIN, opacity: active !== null && !on ? 0.35 : 1 }} transition={{ scaleY: grow(i), opacity: instant(DIM) }}>
                            {SERIES.map((s, si) => (<motion.span key={s.key} className={`art:block art:w-full ${s.color}`} style={{ flexBasis: 0 }} initial={{ flexGrow: 0, opacity: 1 }} animate={{ flexGrow: visible[si] ? day[si] : 0, opacity: highlight !== null && highlight !== si ? 0.25 : 1 }} transition={{ flexGrow: instant(ARTEMIS_SPRING_LAYOUT), opacity: instant(DIM) }}/>))}
                          </motion.span>
                        </button>);
        })}
                    {Array.from({ length: projectedCount }, (_, j) => {
            const i = shown.length + j;
            const date = first + i + 1;
            return (<button key={`${range}-${date}`} type="button" className={BAR} disabled tabIndex={-1} aria-label={`Oct ${date}, projected ${k(average)}`} aria-pressed="false">
                          <span aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 art:opacity-0"/>
                          <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md art:border art:border-foreground/25 art:border-dashed" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: average / DOMAIN, opacity: 1 }} transition={{ scaleY: grow(i), opacity: instant(DIM) }}/>
                        </button>);
        })}
                  </div>
                </div>
                <div aria-hidden="true" className="art:relative art:mt-3 art:h-4 art:font-mono art:text-muted-foreground art:text-xs">
                  <span className="art:absolute art:top-0 art:whitespace-nowrap art:left-0">{`Oct ${first + 1}`}</span>
                  {range === "cycle" ? (<span className="art:absolute art:top-0 art:whitespace-nowrap art:-translate-x-1/2 art:text-foreground" style={{ left: `${((TODAY + 0.5) / count) * 100}%` }}>
                      <span className="art:hidden art:@min-[640px]/artemis:inline">
                        {"Today"}
                        {" \u00B7 "}
                      </span>
                      {`Oct ${TODAY + 1}`}
                    </span>) : null}
                  <span className="art:absolute art:top-0 art:whitespace-nowrap art:right-0">{`Oct ${first + count}`}</span>
                </div>
              </figure>
              <div className="art:flex art:flex-wrap art:gap-2 art:mt-5 art:border-border art:border-t art:pt-5">
                {SERIES.map((s) => {
            const off = hidden.has(s.key);
            const lastOn = !off && SERIES.length - hidden.size === 1;
            return (<motion.button key={s.key} type="button" className={`${LEGEND}${off ? " art:opacity-50" : ""} art:rounded-full`} aria-pressed={!off} aria-disabled={lastOn || undefined} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => !lastOn && toggle(s.key)}>
                      <span className={`art:size-2 art:rounded-full art:transition-transform art:duration-200 ${s.color}${off ? " art:scale-50" : ""}`}/>
                      {s.label}
                    </motion.button>);
        })}
              </div>
            </motion.div>
            <motion.div className="art:min-w-0 art:rounded-3xl art:border art:border-border art:p-5 art:@min-[640px]/artemis:p-6" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.24))}>
              <h3 className="art:font-medium art:text-xl">{"Top workflows"}</h3>
