            const s = SERIES[w.series];
            const faded = highlight !== null && highlight !== w.series;
            return (<li key={w.name} className={`art:flex art:items-center art:gap-3 art:rounded-2xl art:py-2.5 art:transition-opacity art:duration-200${faded ? " art:opacity-40" : ""}`} onPointerEnter={() => setHighlight(w.series)} onPointerLeave={() => setHighlight((h) => (h === w.series ? null : h))}>
