                        <p className="art:mt-0.5 art:flex art:items-center art:gap-1.5 art:text-muted-foreground art:text-xs">
                          <span className={`art:size-1.5 art:rounded-full ${s.color}`}/>
                          {s.label}
                        </p>
                      </div>
                      <svg viewBox="0 0 64 24" className="art:h-6 art:w-16 art:shrink-0 art:overflow-visible" aria-hidden="true">
                        <motion.polyline points={w.points} pathLength="1" fill="none" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 1" className={s.stroke} initial={{ strokeDashoffset: 1 }} animate={{ strokeDashoffset: 0 }} transition={instant({ duration: 0.9, ease: ARTEMIS_EASE_OUT, delay: 0.5 + i * 0.08 })}/>
                      </svg>
                      <div className="art:w-16 art:shrink-0 art:text-right">
                        <p className="art:font-mono art:text-sm art:tabular-nums">{w.value}</p>
                        <p className="art:mt-0.5 art:inline-flex art:items-center art:gap-0.5 art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">
                          {w.up ? (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3" aria-hidden="true">
                              <path d="M7 7h10v10"/>
                              <path d="M7 17 17 7"/>
                            </svg>) : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down-right art:size-3" aria-hidden="true">
                              <path d="m7 7 10 10"/>
                              <path d="M17 7v10H7"/>
                            </svg>)}
                          {w.pct}
                          {"%"}
                          <span className="art:sr-only">{w.up ? "increase" : "decrease"}</span>
                        </p>
                      </div>
                    </li>);
        })}
              </ul>
            </motion.div>
          </div>
        </div>
      </section>
    </>);
}
function Stat({ label, value, badge }: {
    label: string;
    value: string;
    badge?: ReactNode;
}) {
    return (<div className="art:flex art:flex-col-reverse art:gap-1 art:rounded-3xl art:border art:border-border art:p-5">
      <dt className="art:text-muted-foreground art:text-sm">{label}</dt>
      <dd className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3">
